/// <reference path="../edge-runtime.d.ts" />
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  getUserFromBearer,
  linkedinContentJson,
  linkedinContentCorsHeaders,
  requireActiveOrg,
  requireOrgAdmin,
  requireLinkedInContentPlatformConfigured,
} from "../_shared/linkedinContentAuth.ts";
import { cancelScheduleById } from "../_shared/scheduledPosts/scheduledPostCancel.ts";
import { assertPlatformCanSchedule } from "../_shared/scheduledPosts/platformRegistry.ts";
import { runScheduledPostJob } from "../_shared/scheduledPosts/runScheduledPostJob.ts";
import { runPostNowInBackground } from "../_shared/scheduledPosts/schedulePostNowAsync.ts";
import { insertPlatformScheduleForTarget } from "../_shared/scheduledPosts/createPlatformScheduleRow.ts";
import {
  isActiveOrganizationMember,
  mcpScheduleUserId,
} from "../_shared/scheduledPosts/scheduledPostsInternalAuth.ts";
import {
  carouselMediaSnapshot,
  loadCarouselStoragePaths,
} from "../_shared/scheduledPosts/carouselImagePaths.ts";
import {
  getLinkedInPlanEligibilityMissingReasons,
  isCarouselContentType,
  isPlanEligibleForLinkedInAutoSchedule,
} from "../_shared/scheduledPosts/scheduledPostEligibility.ts";

async function loadPlanForPublish(admin: ReturnType<typeof createClient>, planId: string) {
  const { data, error } = await admin
    .from("social_media_plans")
    .select(
      "id, organization_id, post_date, approved, production_approved, google_drive_link, content_type:content_types(name)",
    )
    .eq("id", planId)
    .maybeSingle();
  if (error || !data) return null;
  return data as {
    id: string;
    organization_id: string;
    post_date: string | null;
    approved: boolean;
    production_approved: boolean;
    google_drive_link: string | null;
    content_type?: { name?: string } | null;
  };
}

function mapScheduleInsertError(msg: string): { body: Record<string, unknown>; status: number } {
  if (msg === "publish_scopes_not_granted" || msg === "upload_scopes_not_granted") {
    return { body: { error: msg }, status: 403 };
  }
  if (msg === "linkedin_account_not_found") {
    return { body: { error: msg }, status: 404 };
  }
  if (msg === "invalid_scheduled_at" || msg === "invalid_target") {
    return { body: { error: msg }, status: 400 };
  }
  if (msg === "already_publishing") {
    return { body: { error: msg }, status: 409 };
  }
  return { body: { error: "Failed to create schedule" }, status: 500 };
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { status: 200, headers: linkedinContentCorsHeaders });
  }
  if (req.method !== "POST") return linkedinContentJson({ error: "Method not allowed" }, 405);

  const platformForbidden = requireLinkedInContentPlatformConfigured();
  if (platformForbidden) return platformForbidden;

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceRoleKey) return linkedinContentJson({ error: "Server misconfigured" }, 500);

  const admin = createClient(supabaseUrl, serviceRoleKey);
  let body: Record<string, unknown>;
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    return linkedinContentJson({ error: "Invalid JSON body" }, 400);
  }

  const action = String(body.action ?? "").trim();
  const organizationId = String(body.organization_id ?? "").trim();
  if (!organizationId) return linkedinContentJson({ error: "Missing organization_id" }, 400);

  const isInternalExecute = action === "execute" &&
    body.internal_secret === Deno.env.get("SCHEDULED_POSTS_INTERNAL_SECRET");
  const mcpUserId = mcpScheduleUserId(action, body);

  let userId: string | null = null;
  if (mcpUserId) {
    const member = await isActiveOrganizationMember(admin, mcpUserId, organizationId);
    if (!member) return linkedinContentJson({ error: "Forbidden" }, 403);
    const adminForbidden = await requireOrgAdmin(admin, mcpUserId, organizationId);
    if (adminForbidden) return adminForbidden;
    userId = mcpUserId;
  } else if (!isInternalExecute) {
    const userRes = await getUserFromBearer(admin, req.headers.get("Authorization"));
    if ("error" in userRes) return userRes.error;
    userId = userRes.userId;
    const orgForbidden = await requireActiveOrg(admin, userRes.userId, organizationId);
    if (orgForbidden) return orgForbidden;
    const adminForbidden = await requireOrgAdmin(admin, userRes.userId, organizationId);
    if (adminForbidden) return adminForbidden;
  }

  if (action === "cancel") {
    const scheduleId = String(body.schedule_id ?? "").trim();
    const ok = await cancelScheduleById(admin, scheduleId);
    return linkedinContentJson({ ok }, ok ? 200 : 400);
  }

  if (action === "execute") {
    if (!isInternalExecute) return linkedinContentJson({ error: "Forbidden" }, 403);
    const scheduleId = String(body.schedule_id ?? "").trim();
    const job = await runScheduledPostJob(admin, scheduleId);
    if (!job.ok) return linkedinContentJson({ error: job.error ?? "publish_failed" }, 500);
    return linkedinContentJson({
      ok: true,
      published_url: job.published_url,
      external_post_id: job.external_post_id,
    }, 200);
  }

  const planId = String(body.social_media_plan_id ?? "").trim();
  const plan = await loadPlanForPublish(admin, planId);
  if (!plan || plan.organization_id !== organizationId) {
    return linkedinContentJson({ error: "Plan not found" }, 404);
  }

  const contentTypeName = plan.content_type?.name ?? null;
  const carousel = isCarouselContentType(contentTypeName);
  const carouselPaths = carousel ? await loadCarouselStoragePaths(admin, planId) : [];
  const eligibility = {
    post_date: plan.post_date,
    approved: plan.approved,
    production_approved: plan.production_approved,
    google_drive_link: plan.google_drive_link,
    content_type_name: contentTypeName,
    carousel_image_count: carousel ? carouselPaths.length : undefined,
  };

  if (action === "schedule" || action === "post_now") {
    try {
      assertPlatformCanSchedule("LinkedIn");
    } catch (e) {
      return linkedinContentJson({ error: e instanceof Error ? e.message : "platform_not_supported" }, 400);
    }

    if (!isPlanEligibleForLinkedInAutoSchedule(eligibility)) {
      return linkedinContentJson({
        error: "plan_not_eligible",
        missing: getLinkedInPlanEligibilityMissingReasons(eligibility),
      }, 400);
    }

    const pageId = String(body.page_id ?? "").trim();
    if (!pageId) return linkedinContentJson({ error: "Missing page_id" }, 400);

    const scheduledAtRaw = action === "post_now"
      ? new Date().toISOString()
      : String(body.scheduled_at ?? "").trim();
    if (!scheduledAtRaw) return linkedinContentJson({ error: "Missing scheduled_at" }, 400);

    const driveLink = carousel
      ? carouselMediaSnapshot(carouselPaths)
      : (plan.google_drive_link?.trim() ?? "");

    let inserted;
    try {
      inserted = await insertPlatformScheduleForTarget(admin, {
        organizationId,
        planId,
        driveLink,
        caption: body.caption != null ? String(body.caption) : null,
        title: body.title != null ? String(body.title) : null,
        employeeId: body.employee_id != null ? String(body.employee_id) : null,
        userId,
        action: action as "schedule" | "post_now",
        scheduledAtIso: scheduledAtRaw,
        mediaSource: carousel ? "carousel_images" : null,
        target: {
          platform: "LinkedIn",
          account_id: pageId,
          account_label: body.account_label != null ? String(body.account_label) : "",
        },
      });
    } catch (e) {
      const msg = e instanceof Error ? e.message : "schedule_insert_failed";
      const mapped = mapScheduleInsertError(msg);
      return linkedinContentJson(mapped.body, mapped.status);
    }

    if (action === "post_now") {
      const job = await runPostNowInBackground(admin, inserted.id);
      if ("processing" in job && job.processing) {
        return linkedinContentJson({
          ok: true,
          processing: true,
          schedule: inserted,
        }, 200);
      }
      if (!job.ok) return linkedinContentJson({ error: job.error ?? "publish_failed" }, 500);
      const { data: publishedRow } = await admin
        .from("social_media_scheduled_posts")
        .select("*")
        .eq("id", inserted.id)
        .maybeSingle();
      return linkedinContentJson({
        ok: true,
        schedule: publishedRow ?? inserted,
        published_url: job.published_url,
        external_post_id: job.external_post_id,
      }, 200);
    }

    return linkedinContentJson({ ok: true, schedule: inserted }, 200);
  }

  return linkedinContentJson({ error: "Unknown action" }, 400);
});

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export const linkedinContentCorsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

/** Organic insights, comments, and page admin (Community Management API required). */
export const LINKEDIN_CONTENT_OAUTH_SCOPES_DEFAULT = [
  "r_organization_social",
  "r_organization_social_feed",
  "w_organization_social_feed",
  "w_organization_social",
  "rw_organization_admin",
].join(" ");

/**
 * Personal profile connect (Share on LinkedIn). Used only when connect_kind=person.
 * Do not merge into LINKEDIN_CONTENT_OAUTH_SCOPES_DEFAULT (page path stays org-only).
 */
/**
 * Only request scopes LinkedIn Auth tab accepts on Content Insight.
 * `r_member_social` / `r_member_postAnalytics` caused invalid_scope (not grantable yet) —
 * keep them in LINKEDIN_SCOPE_FEATURE_MAP.memberInsights for status UI, not in authorize URL.
 */
export const LINKEDIN_CONTENT_MEMBER_OAUTH_SCOPES_DEFAULT = [
  "w_member_social",
  "r_basicprofile",
].join(" ");

export type LinkedInContentConnectKind = "organization" | "person";

export const LINKEDIN_SCOPE_FEATURE_MAP = {
  insights: ["r_organization_social"] as const,
  comments: ["r_organization_social_feed", "w_organization_social_feed"] as const,
  publish: ["w_organization_social"] as const,
  /** Personal profile publish (Share on LinkedIn). Requested via member OAuth only. */
  memberPublish: ["w_member_social"] as const,
  /** Personal profile insights (Posts finder + memberCreatorPostAnalytics). */
  memberInsights: ["r_member_social", "r_member_postAnalytics"] as const,
  pages: ["rw_organization_admin"] as const,
} as const;

export function parseLinkedInGrantedScopes(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.map(String);
  if (typeof raw === "string") {
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (Array.isArray(parsed)) return parsed.map(String);
    } catch {
      return raw.split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
    }
  }
  return [];
}

export function missingLinkedInScopesForFeature(
  granted: string[],
  feature: keyof typeof LINKEDIN_SCOPE_FEATURE_MAP,
): string[] {
  const required = LINKEDIN_SCOPE_FEATURE_MAP[feature];
  const grantedSet = new Set(granted.map((s) => s.toLowerCase()));
  return required.filter((s) => !grantedSet.has(s.toLowerCase()));
}

export function linkedinContentOAuthScopes(): string {
  const explicit = Deno.env.get("LINKEDIN_CONTENT_OAUTH_SCOPES")?.trim();
  return explicit || LINKEDIN_CONTENT_OAUTH_SCOPES_DEFAULT;
}

export function linkedinContentMemberOAuthScopes(): string {
  const explicit = Deno.env.get("LINKEDIN_CONTENT_MEMBER_OAUTH_SCOPES")?.trim();
  return explicit || LINKEDIN_CONTENT_MEMBER_OAUTH_SCOPES_DEFAULT;
}

export function parseLinkedInConnectKind(raw: unknown): LinkedInContentConnectKind {
  return String(raw ?? "").trim() === "person" ? "person" : "organization";
}

export function linkedinContentJson(body: object, status: number): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...linkedinContentCorsHeaders, "Content-Type": "application/json" },
  });
}

export function readPlatformLinkedInContentOAuth(): { clientId: string; clientSecret: string } | null {
  const clientId = Deno.env.get("LINKEDIN_CONTENT_CLIENT_ID")?.trim() ?? "";
  const clientSecret = Deno.env.get("LINKEDIN_CONTENT_CLIENT_SECRET")?.trim() ?? "";
  if (!clientId || !clientSecret) return null;
  return { clientId, clientSecret };
}

export function isLinkedInContentPlatformConfigured(): boolean {
  return readPlatformLinkedInContentOAuth() !== null;
}

export function requireLinkedInContentPlatformConfigured(): Response | null {
  if (!isLinkedInContentPlatformConfigured()) {
    return linkedinContentJson(
      {
        error:
          "LinkedIn Content is not configured. Set LINKEDIN_CONTENT_CLIENT_ID and LINKEDIN_CONTENT_CLIENT_SECRET in Supabase Edge Function secrets.",
      },
      503,
    );
  }
  return null;
}

export function linkedinContentOAuthRedirectUri(): string {
  const explicit = Deno.env.get("LINKEDIN_CONTENT_OAUTH_REDIRECT_URI")?.trim();
  if (explicit) return explicit;
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").replace(/\/+$/, "");
  return `${supabaseUrl}/functions/v1/linkedin-content-api`;
}

export function appPublicOrigin(): string {
  const raw =
    Deno.env.get("APP_PUBLIC_URL")?.trim() ??
    Deno.env.get("SYNCKERJA_APP_URL")?.trim() ??
    "";
  return raw.replace(/\/+$/, "");
}

export const LINKEDIN_CONTENT_OAUTH_RETURN_PATHS = new Set([
  "/digital-marketing/social-media-performance/linkedin/settings",
]);

export async function getUserFromBearer(
  admin: SupabaseClient,
  authHeader: string | null,
): Promise<{ userId: string } | { error: Response }> {
  const token = authHeader?.startsWith("Bearer ") ? authHeader.slice("Bearer ".length).trim() : "";
  if (!token) return { error: linkedinContentJson({ error: "Unauthorized" }, 401) };
  const { data: userRes, error: userErr } = await admin.auth.getUser(token);
  if (userErr || !userRes?.user?.id) {
    return { error: linkedinContentJson({ error: "Invalid token" }, 401) };
  }
  return { userId: userRes.user.id };
}

export async function isOmnichannelContentAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<boolean> {
  const { data: owner } = await admin
    .from("user_roles")
    .select("id")
    .eq("user_id", userId)
    .eq("organization_id", organizationId)
    .eq("role", "owner")
    .maybeSingle();
  if (owner) return true;

  const { data: staffRows } = await admin
    .from("organization_omnichannel_staff")
    .select("employee_id, employees!inner(user_id)")
    .eq("organization_id", organizationId)
    .eq("role", "admin");

  for (const row of staffRows ?? []) {
    const emp = row as { employees?: { user_id?: string } | { user_id?: string }[] };
    const employees = emp.employees;
    const userIds: string[] = [];
    if (Array.isArray(employees)) {
      for (const e of employees) {
        if (e?.user_id) userIds.push(String(e.user_id));
      }
    } else if (employees && typeof employees === "object" && "user_id" in employees) {
      const uid = (employees as { user_id?: string }).user_id;
      if (uid) userIds.push(String(uid));
    }
    if (userIds.includes(userId)) return true;
  }
  return false;
}

export async function requireOrgAdmin(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const ok = await isOmnichannelContentAdmin(admin, userId, organizationId);
  if (!ok) return linkedinContentJson({ error: "Forbidden" }, 403);
  return null;
}

export async function requireActiveOrg(
  admin: SupabaseClient,
  userId: string,
  organizationId: string,
): Promise<Response | null> {
  const { data: profile } = await admin
    .from("profiles")
    .select("active_organization_id")
    .eq("user_id", userId)
    .maybeSingle();
  const activeOrg = profile?.active_organization_id != null ? String(profile.active_organization_id) : "";
  if (!activeOrg || activeOrg !== organizationId) {
    return linkedinContentJson({ error: "Forbidden" }, 403);
  }
  return null;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export async function cancelPendingSchedulesForPlan(
  admin: SupabaseClient,
  planId: string,
  reason = "cancelled",
): Promise<number> {
  const { data, error } = await admin
    .from("social_media_scheduled_posts")
    .update({
      status: "cancelled",
      error_message: reason,
      updated_at: new Date().toISOString(),
    })
    .eq("social_media_plan_id", planId)
    .in("status", ["pending", "publishing"])
    .select("id");

  if (error) {
    console.error("cancelPendingSchedulesForPlan:", error.message);
    return 0;
  }
  return (data ?? []).length;
}

export async function cancelScheduleById(
  admin: SupabaseClient,
  scheduleId: string,
  reason = "cancelled_by_user",
): Promise<boolean> {
  const { error } = await admin
    .from("social_media_scheduled_posts")
    .update({
      status: "cancelled",
      error_message: reason,
      updated_at: new Date().toISOString(),
    })
    .eq("id", scheduleId)
    .in("status", ["pending", "publishing"]);

  return !error;
}

function providerConfigAccountField(platform: string): string | null {
  switch (platform.trim()) {
    case "TikTok":
      return "open_id";
    case "YouTube":
      return "channel_id";
    case "Instagram":
      return "instagram_business_account_id";
    case "LinkedIn":
      return "page_id";
    default:
      return null;
  }
}

/** Cancel only pending/publishing schedules for the same platform + OAuth account on a plan. */
export async function cancelPendingSchedulesForPlatformAccount(
  admin: SupabaseClient,
  planId: string,
  platform: string,
  accountId: string,
): Promise<void> {
  const accountTrim = String(accountId ?? "").trim();
  if (!accountTrim) return;

  const configField = providerConfigAccountField(platform);
  if (!configField) {
    await admin
      .from("social_media_scheduled_posts")
      .update({ status: "cancelled", updated_at: new Date().toISOString() })
      .eq("social_media_plan_id", planId)
      .eq("platform", platform)
      .in("status", ["pending", "publishing"]);
    return;
  }

  const { error } = await admin
    .from("social_media_scheduled_posts")
    .update({ status: "cancelled", updated_at: new Date().toISOString() })
    .eq("social_media_plan_id", planId)
    .eq("platform", platform)
    .filter(`provider_config->>${configField}`, "eq", accountTrim)
    .in("status", ["pending", "publishing"]);

  if (error) {
    console.error("cancelPendingSchedulesForPlatformAccount:", error.message);
  }
}

export type PlatformStubCode = "manual_only" | "not_implemented";

export type PlatformScheduleCapability =
  | { deliveryMode: "api_auto"; implemented: true }
  | { deliveryMode: "manual_only"; implemented: false; stubCode: "manual_only" }
  | { deliveryMode: "api_auto"; implemented: false; stubCode: "not_implemented" };

export const PLATFORM_SCHEDULE_REGISTRY: Record<string, PlatformScheduleCapability> = {
  TikTok: { deliveryMode: "api_auto", implemented: true },
  Instagram: { deliveryMode: "api_auto", implemented: true },
  Facebook: { deliveryMode: "api_auto", implemented: true },
  YouTube: { deliveryMode: "api_auto", implemented: true },
  LinkedIn: { deliveryMode: "api_auto", implemented: true },
};

export function normalizeSchedulePlatform(platform: string): string {
  return platform.trim();
}

export function getPlatformScheduleCapability(platform: string): PlatformScheduleCapability | null {
  const key = normalizeSchedulePlatform(platform);
  return PLATFORM_SCHEDULE_REGISTRY[key] ?? null;
}

export function assertPlatformCanSchedule(platform: string): void {
  const capability = getPlatformScheduleCapability(platform);
  if (!capability) {
    throw new Error(`schedule_stub:not_implemented:${normalizeSchedulePlatform(platform)}:Unknown platform`);
  }
  if (!capability.implemented) {
    throw new Error(
      `schedule_stub:${capability.stubCode}:${normalizeSchedulePlatform(platform)}:${capability.deliveryMode}`,
    );
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { executeScheduledPost } from "./executeScheduledPost.ts";
import type { SchedulerConfig } from "./config/schedulerConfigTypes.ts";
import { DEFAULT_SCHEDULER_CONFIG } from "./config/schedulerConfigTypes.ts";
import { shouldDryRunPublish } from "./dryRun/shouldDryRunPublish.ts";
import { parseScheduleStubError, isScheduleStubError } from "./platforms/stubErrors.ts";
import { acquirePublishSlot } from "./rateLimit/acquirePublishSlot.ts";
import { countGlobalInFlightPublishing } from "./rateLimit/countGlobalInFlight.ts";
import { globalInFlightCapForPlatform } from "./config/globalInFlightCap.ts";
import {
  deferForRateLimit,
  isPublishResumeRow,
  stripPublishResumeFlags,
} from "./rateLimit/deferForRateLimit.ts";
import {
  computeNextRetryAt,
  isInternalRateLimitMessage,
  isTransientPublishErrorForPlatform,
  resolveScheduleStatusAfterFailure,
  sleepMs,
} from "./scheduledPostRetry.ts";
import type { ScheduledPostRow } from "./scheduledPostTypes.ts";
import { touchPublishingHeartbeat } from "./publishingHeartbeat.ts";
import type { SharedPublishContext } from "./sharedPublishContext.ts";
import { syncPlanCompletionStateForPlan } from "./syncPlanCompletionStateDb.ts";
import { attachPublishedPostToLeadMagnet } from "../leadMagnet/attachPublishedPost.ts";

export type RunScheduledPostJobResult = {
  id: string;
  ok: boolean;
  platform: string;
  error?: string;
  stubCode?: "manual_only" | "not_implemented";
  published_url?: string;
  external_post_id?: string;
  tiktok_publish_path?: "pull" | "file_upload" | "photo_pull";
  retry_count?: number;
  skipped?: "already_published" | "already_claimed";
  deferred?: "rate_limit" | "rate_limit_global" | "tick_budget";
};

export type RunScheduledPostJobOptions = {
  /** Row already transitioned to publishing by claim RPC. */
  fromClaim?: boolean;
  /** post_now: row inserted as publishing. */
  skipPublishingTransition?: boolean;
  preloadedRow?: ScheduledPostRow;
  schedulerConfig?: SchedulerConfig;
  /** Shared Drive download for plan bulk orchestrator */
  sharedPublishContext?: SharedPublishContext;
  /** One immediate retry already ran for this invocation. */
  inlineRetried?: boolean;
};


async function enforcePublishRateLimits(
  admin: SupabaseClient,
  row: ScheduledPostRow,
  schedulerConfig: SchedulerConfig,
): Promise<
  | { allowed: true }
  | { allowed: false; deferred: "rate_limit" | "rate_limit_global"; reason: string }
> {
  if (shouldDryRunPublish(row)) {
    return { allowed: true };
  }

  const providerConfig = row.provider_config ?? {};
  const isResume = isPublishResumeRow(row.platform, providerConfig);
  const globalCap = globalInFlightCapForPlatform(row.platform, schedulerConfig);

  if (globalCap !== null) {
    const inFlight = await countGlobalInFlightPublishing(admin, row.platform);
    if (inFlight > globalCap) {
      const reason = "rate_limited:global";
      await deferForRateLimit(admin, row.id, reason);
      return { allowed: false, deferred: "rate_limit_global", reason };
    }
  }

  if (!isResume) {
    const acquired = await acquirePublishSlot(admin, row.organization_id, row.platform);
    if (!acquired) {
      const reason = "rate_limited:org";
      await deferForRateLimit(admin, row.id, reason);
      return { allowed: false, deferred: "rate_limit", reason };
    }
  }

  return { allowed: true };
}

export async function runScheduledPostJob(
  admin: SupabaseClient,
  scheduleId: string,
  options?: RunScheduledPostJobOptions,
): Promise<RunScheduledPostJobResult> {
  let row: ScheduledPostRow | null = options?.preloadedRow ?? null;

  if (!row) {
    const { data: schedule, error: schedErr } = await admin
      .from("social_media_scheduled_posts")
      .select("*")
      .eq("id", scheduleId)
      .maybeSingle();

    if (schedErr || !schedule) {
      return { id: scheduleId, ok: false, platform: "unknown", error: "Schedule not found" };
    }
    row = schedule as ScheduledPostRow;
  }

  const platform = row.platform;

  if (row.status === "published" || row.external_post_id) {
    return {
      id: scheduleId,
      ok: true,
      platform,
      published_url: row.published_url ?? undefined,
      external_post_id: row.external_post_id,
      skipped: "already_published",
    };
  }

  if (row.status !== "pending" && row.status !== "publishing") {
    return {
      id: scheduleId,
      ok: false,
      platform,
      error: `Schedule not runnable (${row.status})`,
    };
  }

  if (options?.fromClaim) {
    if (row.status !== "publishing") {
      return {
        id: scheduleId,
        ok: false,
        platform,
        error: "Claimed row not in publishing state",
      };
    }
  } else if (options?.skipPublishingTransition) {
    if (row.status !== "publishing") {
      return {
        id: scheduleId,
        ok: false,
        platform,
        error: "post_now row must be publishing",
      };
    }
  } else if (row.status === "publishing") {
    return {
      id: scheduleId,
      ok: false,
      platform,
      error: "already_claimed",
      skipped: "already_claimed",
    };
  } else {
    const now = new Date().toISOString();
    const { data: locked, error: lockErr } = await admin
      .from("social_media_scheduled_posts")
      .update({
        status: "publishing",
        locked_at: now,
        updated_at: now,
      })
      .eq("id", scheduleId)
      .eq("status", "pending")
      .select("*")
      .maybeSingle();

    if (lockErr) {
      return { id: scheduleId, ok: false, platform, error: lockErr.message };
    }
    if (!locked) {
      return {
        id: scheduleId,
        ok: false,
        platform,
        error: "already_claimed",
        skipped: "already_claimed",
      };
    }
    row = locked as ScheduledPostRow;
  }

  const schedulerConfig = options?.schedulerConfig ?? DEFAULT_SCHEDULER_CONFIG;

  const rateLimit = await enforcePublishRateLimits(admin, row, schedulerConfig);
  if (!rateLimit.allowed) {
    return {
      id: scheduleId,
      ok: false,
      platform,
      error: rateLimit.reason,
      deferred: rateLimit.deferred,
    };
  }

  try {
    await touchPublishingHeartbeat(admin, [scheduleId]);
    const result = await executeScheduledPost(admin, row, options?.sharedPublishContext);
    // Executors persist publish metadata mid-run, so strip from the latest row, not the stale one.
    const { data: latest } = await admin
      .from("social_media_scheduled_posts")
      .select("provider_config")
      .eq("id", scheduleId)
      .maybeSingle();
    const cleanedConfig = stripPublishResumeFlags(
      platform,
      (latest?.provider_config as Record<string, unknown> | null) ?? row.provider_config ?? {},
    );
    const { data: publishedRows, error: publishError } = await admin
      .from("social_media_scheduled_posts")
      .update({
        status: "published",
        published_url: result.published_url,
        external_post_id: result.external_post_id,
        published_at: new Date().toISOString(),
        error_message: null,
        next_retry_at: null,
        locked_at: null,
        last_error_at: null,
        provider_config: cleanedConfig,
        updated_at: new Date().toISOString(),
      })
      .eq("id", scheduleId)
      .eq("status", "publishing")
      .select("id");
    if (publishError) throw publishError;
    if (!publishedRows?.length) {
      return {
        id: scheduleId,
        ok: false,
        platform,
        error: "publish_superseded",
      };
    }

    // Link upsert syncs while this row is still "publishing", which does not count as done.
    await syncPlanCompletionStateForPlan(admin, row.social_media_plan_id);

    if (result.external_post_id && (platform === "Instagram" || platform === "Facebook")) {
      try {
        await attachPublishedPostToLeadMagnet(admin, {
          organizationId: row.organization_id,
          planId: row.social_media_plan_id,
          platform,
          mediaId: result.external_post_id,
          permalink: result.published_url ?? null,
        });
      } catch (attachError) {
        console.error(
          "[lead-magnet] attach post failed",
          attachError instanceof Error ? attachError.message : attachError,
        );
      }
    }

    return {
      id: scheduleId,
      ok: true,
      platform,
      published_url: result.published_url,
      external_post_id: result.external_post_id,
      tiktok_publish_path: result.tiktok_publish_path,
    };
  } catch (e) {
    const msg = e instanceof Error ? e.message : "publish_failed";
    const stub = parseScheduleStubError(msg);
    if (
      !options?.inlineRetried &&
      !stub &&
      !isScheduleStubError(msg) &&
      !isInternalRateLimitMessage(msg) &&
      isTransientPublishErrorForPlatform(platform, msg)
    ) {
      await sleepMs(3000);
      return runScheduledPostJob(admin, scheduleId, {
        ...options,
        inlineRetried: true,
        preloadedRow: undefined,
        fromClaim: true,
      });
    }
    const retryCount = isInternalRateLimitMessage(msg)
      ? Number(row.retry_count ?? 0)
      : Number(row.retry_count ?? 0) + 1;
    const nextStatus = stub || isScheduleStubError(msg)
      ? "failed"
      : resolveScheduleStatusAfterFailure(retryCount, msg, platform);
    const nextRetryAt = nextStatus === "pending"
      ? computeNextRetryAt(retryCount, msg, platform)
      : null;
    const now = new Date().toISOString();

    await admin
      .from("social_media_scheduled_posts")
      .update({
        status: nextStatus,
        error_message: msg,
        retry_count: retryCount,
        next_retry_at: nextRetryAt,
        last_error_at: now,
        locked_at: null,
        updated_at: now,
      })
      .eq("id", scheduleId)
      .eq("status", "publishing");

    return {
      id: scheduleId,
      ok: false,
      platform,
      error: msg,
      stubCode: stub?.stubCode,
      retry_count: retryCount,
    };
  }
}

