type TikTokContentError = {
  code?: string;
  message?: string;
  log_id?: string;
};

type TikTokContentEnvelope<T> = {
  data?: T;
  error?: TikTokContentError;
};

export type TikTokVideoRow = {
  id?: string;
  title?: string;
  create_time?: number;
  share_url?: string;
  cover_image_url?: string;
  view_count?: number;
  like_count?: number;
