export type PlanEligibilityInput = {
  post_date: string | null;
  approved: boolean;
  production_approved: boolean;
  google_drive_link: string | null;
  content_type_name: string | null;
  /** Set for TikTok photo carousel. Reel checks ignore it. */
  carousel_image_count?: number | null;
};

export type PlanAutoScheduleEligibilityInput = PlanEligibilityInput & {
  service_id: string | null;
};

export function isReelContentType(contentTypeName: string | null | undefined): boolean {
  return String(contentTypeName ?? "").trim().toLowerCase() === "reel";
}

export function isCarouselContentType(contentTypeName: string | null | undefined): boolean {
  const name = String(contentTypeName ?? "").trim().toLowerCase();
  return name === "post" || name === "carousel";
}

export function getTikTokPlanEligibilityMissingReasons(plan: PlanEligibilityInput): string[] {
  if (!isCarouselContentType(plan.content_type_name)) {
    return getPlanEligibilityMissingReasons(plan);
  }
  const reasons: string[] = [];
  if (!plan.post_date) reasons.push("post_date");
  if (!plan.approved) reasons.push("approved");
  if (!plan.production_approved) reasons.push("production_approved");
  const count = plan.carousel_image_count ?? 0;
  if (count < 1) reasons.push("carousel_images");
  else if (count > CAROUSEL_PUBLISH_IMAGE_LIMIT) reasons.push("carousel_image_limit");
  return reasons;
}

export function isPlanEligibleForTikTokCarouselSchedule(plan: PlanEligibilityInput): boolean {
  return isCarouselContentType(plan.content_type_name) &&
    getTikTokPlanEligibilityMissingReasons(plan).length === 0;
}

export function isPlanEligibleForTikTokAutoSchedule(plan: PlanEligibilityInput): boolean {
  if (isCarouselContentType(plan.content_type_name)) {
    return isPlanEligibleForTikTokCarouselSchedule(plan);
  }
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function isPlanEligibleForYouTubeAutoSchedule(plan: PlanEligibilityInput): boolean {
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function getInstagramPlanEligibilityMissingReasons(plan: PlanEligibilityInput): string[] {
  if (!isCarouselContentType(plan.content_type_name)) {
    return getPlanEligibilityMissingReasons(plan);
  }
  return getTikTokPlanEligibilityMissingReasons(plan);
}

export function isPlanEligibleForInstagramAutoSchedule(plan: PlanEligibilityInput): boolean {
  if (isCarouselContentType(plan.content_type_name)) {
    return isPlanEligibleForTikTokCarouselSchedule(plan);
  }
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function getFacebookPlanEligibilityMissingReasons(plan: PlanEligibilityInput): string[] {
  if (!isCarouselContentType(plan.content_type_name)) {
    return getPlanEligibilityMissingReasons(plan);
  }
  return getTikTokPlanEligibilityMissingReasons(plan);
}

export function isPlanEligibleForFacebookAutoSchedule(plan: PlanEligibilityInput): boolean {
  if (isCarouselContentType(plan.content_type_name)) {
    return isPlanEligibleForTikTokCarouselSchedule(plan);
  }
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function getLinkedInPlanEligibilityMissingReasons(plan: PlanEligibilityInput): string[] {
  if (!isCarouselContentType(plan.content_type_name)) {
    return getPlanEligibilityMissingReasons(plan);
  }
  return getTikTokPlanEligibilityMissingReasons(plan);
}

export function isPlanEligibleForLinkedInAutoSchedule(plan: PlanEligibilityInput): boolean {
  if (isCarouselContentType(plan.content_type_name)) {
    return isPlanEligibleForTikTokCarouselSchedule(plan);
  }
  return isPlanEligibleForReelAutoSchedule(plan);
}

export function isPlanEligibleForReelAutoSchedule(plan: PlanEligibilityInput): boolean {
  if (!plan.post_date) return false;
  if (!plan.approved) return false;
  if (!plan.production_approved) return false;
  if (!isReelContentType(plan.content_type_name)) return false;
  const link = plan.google_drive_link?.trim() ?? "";
  if (!link) return false;
  if (!isGoogleDriveFileLink(link)) return false;
  return true;
}

export function isPlanEligibleForAutoSchedule(plan: PlanAutoScheduleEligibilityInput): boolean {
  if (!isPlanEligibleForReelAutoSchedule(plan)) return false;
  if (!String(plan.service_id ?? "").trim()) return false;
  return true;
}

export function getPlanEligibilityMissingReasons(plan: PlanEligibilityInput): string[] {
  const reasons: string[] = [];
  if (!plan.post_date) reasons.push("post_date");
  if (!isReelContentType(plan.content_type_name)) reasons.push("content_type_reel");
  if (!plan.approved) reasons.push("approved");
  if (!plan.production_approved) reasons.push("production_approved");
  const link = plan.google_drive_link?.trim() ?? "";
  if (!link) reasons.push("google_drive_link");
  else if (!isGoogleDriveFileLink(link)) reasons.push("google_drive_file");
  return reasons;
}

export function shouldCancelScheduleDueToDriveMismatch(
  snapshot: string,
  currentLink: string | null | undefined,
): boolean {
  return !googleDriveLinksSemanticallyEqual(snapshot, currentLink);
}

/** Extract Google Drive file id from share URL. */
export function extractGoogleDriveFileId(url: string): string | null {
  if (!url?.trim()) return null;
  const fileMatch = url.match(/\/file\/d\/([a-zA-Z0-9-_]+)/i);
  if (fileMatch) return fileMatch[1];
  if (url.includes("drive.google.com") && /[?&]id=([a-zA-Z0-9-_]+)/i.test(url)) {
    const openMatch = url.match(/[?&]id=([a-zA-Z0-9-_]+)/i);
    if (openMatch) return openMatch[1];
  }
  return null;
}

export function isGoogleDriveFolderLink(url: string): boolean {
  return url.includes("drive.google.com/drive/folders/");
}

export function isGoogleDriveFileLink(url: string): boolean {
  if (!url?.trim()) return false;
  if (isGoogleDriveFolderLink(url)) return false;
  return extractGoogleDriveFileId(url) !== null;
}

/** Direct download URL for public Google Drive video (server-side fetch for TikTok FILE_UPLOAD). */
export function resolveGoogleDrivePublicVideoUrl(url: string): string | null {
  const fileId = extractGoogleDriveFileId(url);
  if (!fileId) return null;
  return `https://drive.usercontent.google.com/download?id=${fileId}&export=download&confirm=t`;
}

export function normalizeGoogleDriveUrl(url: string): string {
  const raw = url?.trim() ?? "";
  if (!raw) return "";
  const fileId = extractGoogleDriveFileId(raw);
  if (fileId && raw.toLowerCase().includes("drive.google.com")) {
    return `file:${fileId}`;
  }
  return raw.toLowerCase().split("?")[0].split("#")[0];
}

export function googleDriveLinksSemanticallyEqual(
  a: string | null | undefined,
  b: string | null | undefined,
): boolean {
  return normalizeGoogleDriveUrl(a ?? "") === normalizeGoogleDriveUrl(b ?? "");
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

/**
 * Refresh locked_at while a worker is alive.
 * Stall recovery treats a publishing row with no heartbeat as stuck, not still uploading.
 */
export async function touchPublishingHeartbeat(
  admin: SupabaseClient,
  scheduleIds: string[],
): Promise<void> {
  const ids = [...new Set(scheduleIds.map((id) => id.trim()).filter(Boolean))];
  if (ids.length === 0) return;
  const now = new Date().toISOString();
  const { error } = await admin
    .from("social_media_scheduled_posts")
    .update({ locked_at: now, updated_at: now })
    .in("id", ids)
    .eq("status", "publishing");
  if (error) {
    console.warn(`publishing_heartbeat_failed: ${error.message}`);
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { downloadGoogleDriveVideo } from "./googleDriveVideoDownload.ts";
import {
  isGoogleDriveFileLink,
  resolveGoogleDrivePublicVideoUrl,
} from "./googleDrivePublicVideoUrl.ts";

export type PreloadedDriveVideo = {
  bytes: Uint8Array;
  mimeType: string;
};

export type SharedPublishContext = {
  driveUrl: string;
  /** Public direct download URL for TikTok PULL_FROM_URL */
  drivePublicDownloadUrl: string | null;
  preloadedVideo?: PreloadedDriveVideo;
};

/** Platforms that always send the file from this worker. Facebook and Instagram pull from a public URL first. */
const PLATFORMS_NEEDING_BYTES = new Set([
  "YouTube",
  "LinkedIn",
]);

/** Download the Drive file only when a platform cannot publish from a public URL. */
export function planPublishNeedsPreloadedVideo(platforms: string[]): boolean {
  const normalized = platforms.map((p) => p.trim());
  if (normalized.some((p) => PLATFORMS_NEEDING_BYTES.has(p))) return true;
  return normalized.includes("TikTok") && !isTikTokPullFromUrlEnabled();
}

export function isTikTokPullFromUrlEnabled(): boolean {
  const raw = Deno.env.get("TIKTOK_PULL_FROM_URL_ENABLED");
  if (raw === undefined || raw === "") return true;
  return raw.toLowerCase() === "true" || raw === "1";
}

export function isPlanPublishSequential(): boolean {
  const raw = Deno.env.get("PLAN_PUBLISH_SEQUENTIAL");
  return raw?.toLowerCase() === "true" || raw === "1";
}

/**
 * Instagram Reels upload to rupload fails with HTTP 400 when it runs in the
 * same moment as Facebook (same Meta app). A later solo retry succeeds, which
 * is why the row sits on Scheduled for several minutes. Upload Instagram after
 * the other platforms in the same job. A container that is already uploaded
 * only needs media_publish and can stay in the parallel batch.
 */
export function instagramPublishShouldFollowPeers(row: {
  platform: string;
  provider_config?: Record<string, unknown> | null;
}): boolean {
  if (row.platform !== "Instagram") return false;
  const phase = String(row.provider_config?.ig_upload_phase ?? "").trim();
  return phase !== "uploaded";
}

/** Each parallel upload must own its bytes. A shared Uint8Array can be detached by the first fetch. */
export function cloneSharedPublishContext(ctx: SharedPublishContext): SharedPublishContext {
  if (!ctx.preloadedVideo) {
    return { driveUrl: ctx.driveUrl, drivePublicDownloadUrl: ctx.drivePublicDownloadUrl };
  }
  return {
    driveUrl: ctx.driveUrl,
    drivePublicDownloadUrl: ctx.drivePublicDownloadUrl,
    preloadedVideo: {
      bytes: ctx.preloadedVideo.bytes.slice(),
      mimeType: ctx.preloadedVideo.mimeType,
    },
  };
}

export async function buildSharedPublishContext(
  driveUrl: string,
  platforms: string[],
): Promise<SharedPublishContext> {
  const trimmed = driveUrl?.trim() ?? "";
  if (!trimmed || !isGoogleDriveFileLink(trimmed)) {
    throw new Error("invalid_google_drive_video_url");
  }

  const drivePublicDownloadUrl = resolveGoogleDrivePublicVideoUrl(trimmed);
  const ctx: SharedPublishContext = {
    driveUrl: trimmed,
    drivePublicDownloadUrl,
  };

  if (planPublishNeedsPreloadedVideo(platforms)) {
    const { bytes, mimeType } = await downloadGoogleDriveVideo(trimmed);
    ctx.preloadedVideo = { bytes, mimeType };
  }

  return ctx;
}

export async function resolveDriveUrlFromPlan(
  admin: SupabaseClient,
  planId: string,
  fallbackSnapshot?: string | null,
): Promise<string> {
  const { data, error } = await admin
    .from("social_media_plans")
    .select("google_drive_link")
    .eq("id", planId)
    .maybeSingle();
  if (error) throw new Error(error.message);
  const link = String(data?.google_drive_link ?? "").trim() || String(fallbackSnapshot ?? "").trim();
  if (!link) throw new Error("google_drive_link");
  return link;
}

export async function resolveVideoBytesForUpload(
  driveUrl: string,
  sharedCtx?: SharedPublishContext,
): Promise<PreloadedDriveVideo> {
  if (sharedCtx?.preloadedVideo) {
    // Copy so a parallel or later upload cannot detach the buffer the next platform still needs.
    return {
      bytes: sharedCtx.preloadedVideo.bytes.slice(),
      mimeType: sharedCtx.preloadedVideo.mimeType,
    };
  }
  const { bytes, mimeType } = await downloadGoogleDriveVideo(driveUrl);
  return { bytes, mimeType };
}

import { DRIVE_DOWNLOAD_TIMEOUT_MS, isFetchAbortError } from "./fetchTimeout.ts";
import { resolveGoogleDrivePublicVideoUrl } from "./googleDrivePublicVideoUrl.ts";
import { resolveValidatedVideoMimeType } from "./validateDownloadedVideo.ts";

/** Keep in sync with Android share copy limit and googleDriveResumableUploadClient. */
const MAX_VIDEO_BYTES = 512 * 1024 * 1024;

function isHtmlResponse(contentType: string | null, bytes: Uint8Array): boolean {
  const type = String(contentType ?? "").toLowerCase();
  if (type.includes("text/html")) return true;
  const head = new TextDecoder().decode(bytes.subarray(0, Math.min(bytes.byteLength, 256))).toLowerCase();
  return head.includes("<!doctype html") || head.includes("<html");
}

/** Download a publicly shared Google Drive video for TikTok FILE_UPLOAD. */
export async function downloadGoogleDriveVideo(
  driveShareUrl: string,
): Promise<{ bytes: Uint8Array; mimeType: string }> {
  const downloadUrl = resolveGoogleDrivePublicVideoUrl(driveShareUrl);
  if (!downloadUrl) throw new Error("invalid_google_drive_video_url");

  const started = Date.now();
  let res: Response;
  try {
    res = await fetch(downloadUrl, {
      redirect: "follow",
      signal: AbortSignal.timeout(DRIVE_DOWNLOAD_TIMEOUT_MS),
    });
  } catch (err) {
    if (isFetchAbortError(err)) {
      throw new Error(
        `drive_download_timeout: Google Drive download did not finish in ${DRIVE_DOWNLOAD_TIMEOUT_MS}ms`,
      );
    }
    throw err;
  }
  if (!res.ok) {
    throw new Error(`drive_download_failed: HTTP ${res.status}`);
  }

  const contentLength = Number(res.headers.get("content-length") ?? "0");
  if (Number.isFinite(contentLength) && contentLength > MAX_VIDEO_BYTES) {
    throw new Error(`drive_video_too_large: ${contentLength} bytes (max ${MAX_VIDEO_BYTES})`);
  }

  const bytes = new Uint8Array(await res.arrayBuffer());
  if (bytes.byteLength === 0) {
    throw new Error("drive_download_failed: empty file");
  }
  if (bytes.byteLength > MAX_VIDEO_BYTES) {
    throw new Error(`drive_video_too_large: ${bytes.byteLength} bytes (max ${MAX_VIDEO_BYTES})`);
  }

  if (isHtmlResponse(res.headers.get("content-type"), bytes)) {
    throw new Error(
      "drive_download_failed: Google Drive returned HTML instead of video. Ensure the file is shared as Anyone with the link can view.",
    );
  }

  const mimeType = resolveValidatedVideoMimeType(bytes, res.headers.get("content-type"));
  console.info(
    `drive_download_ok bytes=${bytes.byteLength} ms=${Date.now() - started} mime=${mimeType}`,
  );

  return { bytes, mimeType };
}

const MIN_VIDEO_BYTES = 10 * 1024;

const MP4_FTYP_BRANDS = new Set([
  "isom",
  "iso2",
  "mp41",
  "mp42",
  "avc1",
  "M4V ",
  "M4A ",
  "qt  ",
]);

function readAscii(bytes: Uint8Array, offset: number, length: number): string {
  return new TextDecoder().decode(bytes.subarray(offset, offset + length));
}

/** Detect MP4/MOV container via ISO BMFF `ftyp` box at offset 4. */
export function detectMp4OrMovMimeType(bytes: Uint8Array): string | null {
  if (bytes.byteLength < 12) return null;
  if (readAscii(bytes, 4, 4) !== "ftyp") return null;

  const majorBrand = readAscii(bytes, 8, 4);
  if (MP4_FTYP_BRANDS.has(majorBrand)) {
    return majorBrand.trim() === "qt" ? "video/quicktime" : "video/mp4";
  }

  // Some CapCut exports use other compatible brands — still accept any ftyp box.
  return "video/mp4";
}

export function validateDownloadedVideoBytes(bytes: Uint8Array): { mimeType: string } {
  if (bytes.byteLength < MIN_VIDEO_BYTES) {
    throw new Error(
      `invalid_video_file: file too small (${bytes.byteLength} bytes). Ensure Google Drive link points to a valid video.`,
    );
  }

  const detected = detectMp4OrMovMimeType(bytes);
  if (!detected) {
    throw new Error(
      "invalid_video_file: not a valid mp4/mov container. Re-export the video as MP4 and upload again.",
    );
  }

  return { mimeType: detected };
}

export function resolveValidatedVideoMimeType(
  bytes: Uint8Array,
  headerContentType: string | null,
): string {
  const validated = validateDownloadedVideoBytes(bytes);
  const header = String(headerContentType ?? "").split(";")[0].trim().toLowerCase();
  if (header.startsWith("video/")) return header;
  return validated.mimeType;
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
