  "threads_basic",
  "threads_manage_insights",
  "threads_read_replies",
  "threads_manage_replies",
  "threads_content_publish",
] as const;

export function hasThreadsScopes(granted: string[]): boolean {
  const grantedSet = new Set(granted.map((s) => s.toLowerCase()));
  return THREADS_OAUTH_SCOPE_LIST.some((s) => grantedSet.has(s.toLowerCase()));
}

export function metaGraphVersion(): string {
  return Deno.env.get("META_GRAPH_API_VERSION")?.trim() || "v22.0";
}

export function missingScopesForFeature(
  granted: string[],
  feature: keyof typeof META_SCOPE_FEATURE_MAP,
): string[] {
  const required = META_SCOPE_FEATURE_MAP[feature];
  const grantedSet = new Set(normalizeGrantedScopes(granted).map((s) => s.toLowerCase()));
  return required.filter((s) => !isScopeGranted(grantedSet, s));
}

export function hasAllScopes(granted: string[], required: readonly string[]): boolean {
  const grantedSet = new Set(normalizeGrantedScopes(granted).map((s) => s.toLowerCase()));
  return required.every((s) => isScopeGranted(grantedSet, s));
}

export function missingScopesForInstagramPublish(granted: string[]): string[] {
  return missingScopesForFeature(granted, "publish");
}

export function missingScopesForFacebookPublish(granted: string[]): string[] {
  return missingScopesForFeature(granted, "facebook_publish");
}

export function instagramPublishScopesOk(granted: string[]): boolean {
  return missingScopesForInstagramPublish(granted).length === 0;
}

export function facebookPublishScopesOk(granted: string[]): boolean {
  return missingScopesForFacebookPublish(granted).length === 0;
}

export async function fetchGrantedPermissions(
  accessToken: string,
  appId?: string,
): Promise<string[]> {
  const version = metaGraphVersion();
  const debugUrl = appId?.trim()
    ? `https://graph.facebook.com/${version}/debug_token?input_token=${encodeURIComponent(accessToken)}&access_token=${encodeURIComponent(appId)}|${encodeURIComponent(Deno.env.get("META_APP_SECRET") ?? "")}`
    : null;

  if (debugUrl) {
    try {
      const res = await fetch(debugUrl);
      const data = await res.json().catch(() => ({})) as {
        data?: { scopes?: string[] };
      };
      if (res.ok && Array.isArray(data?.data?.scopes)) {
        return data.data.scopes.map((s) => String(s));
      }
    } catch {
      /* fall through */
    }
  }

  const permUrl = `https://graph.facebook.com/${version}/me/permissions?access_token=${encodeURIComponent(accessToken)}`;
  const permRes = await fetch(permUrl);
  const permData = await permRes.json().catch(() => ({})) as {
    data?: Array<{ permission?: string; status?: string }>;
  };
  if (!permRes.ok || !Array.isArray(permData?.data)) return [];
  return permData.data
    .filter((p) => p.status === "granted" && p.permission)
    .map((p) => String(p.permission));
}

/** URL fetch failures can still be published by uploading the bytes. A container that is only still processing must keep its id. */
export function shouldFallbackFromInstagramVideoUrl(message: string): boolean {
  const normalized = message.toLowerCase();
  if (normalized.includes("media_not_ready")) return false;
  return (
    normalized.includes("meta_reels_container_error") ||
    normalized.includes("meta_reels_container_expired") ||
    normalized.includes("meta_reels_container http") ||
    normalized.includes("meta_reels_missing")
  );
}

import { graphUrl } from "../metaContentAuth.ts";
import { sleepMs } from "../scheduledPosts/scheduledPostRetry.ts";

export type MetaReelsContainerResult = {
  containerId: string;
  uploadUri: string;
};

export type InstagramContainerStatus = {
  statusCode: string;
  status: string | null;
};

const IG_CONTAINER_READY = "FINISHED";
const IG_CONTAINER_FATAL = new Set(["ERROR", "EXPIRED"]);

/** Default: Meta often finishes in 30s–2m; keep under typical waitUntil budget. */
const DEFAULT_CONTAINER_MAX_WAIT_MS = 180_000;
const DEFAULT_CONTAINER_POLL_MS = 5_000;

export async function createInstagramReelsContainer(
  igBusinessAccountId: string,
  pageAccessToken: string,
  args: { caption: string; videoUrl?: string },
): Promise<MetaReelsContainerResult> {
  const videoUrl = args.videoUrl?.trim() ?? "";
  const params: Record<string, string> = {
    access_token: pageAccessToken,
    media_type: "REELS",
    caption: args.caption.slice(0, 2200),
  };
  if (videoUrl) params.video_url = videoUrl;
  else params.upload_type = "resumable";

  const url = graphUrl(`${igBusinessAccountId}/media`);
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(params),
  });

  const json = await res.json().catch(() => ({})) as {
    id?: string;
    uri?: string;
    error?: { message?: string; code?: number };
  };

  if (!res.ok || !json.id) {
    throw new Error(
      `meta_reels_container HTTP ${res.status}: ${json.error?.message ?? "unknown"}`,
    );
  }

  const uploadUri = String(json.uri ?? "").trim();
  if (!videoUrl && !uploadUri) throw new Error("meta_reels_missing_upload_uri");

  return { containerId: String(json.id), uploadUri };
}

/** Byte upload must not sit open until the 20-minute stale recovery. */
const IG_BYTE_UPLOAD_TIMEOUT_MS = 90_000;

function isUploadAbort(err: unknown): boolean {
  return err instanceof DOMException && (err.name === "TimeoutError" || err.name === "AbortError");
}

export async function uploadInstagramReelsVideo(
  uploadUri: string,
  pageAccessToken: string,
  videoBytes: Uint8Array,
): Promise<void> {
  const body = new Blob([videoBytes], { type: "application/octet-stream" });
  let res: Response;
  try {
    res = await fetch(uploadUri, {
      method: "POST",
      headers: {
        Authorization: `OAuth ${pageAccessToken}`,
        offset: "0",
        file_size: String(videoBytes.byteLength),
      },
      body,
      signal: AbortSignal.timeout(IG_BYTE_UPLOAD_TIMEOUT_MS),
    });
  } catch (err) {
    if (isUploadAbort(err)) {
      throw new Error(
        `ig_upload_timeout: Instagram upload did not finish in ${IG_BYTE_UPLOAD_TIMEOUT_MS}ms`,
      );
    }
    throw err;
  }

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`meta_reels_upload HTTP ${res.status}: ${text.slice(0, 300)}`);
  }
}

export async function fetchInstagramContainerStatus(
  containerId: string,
  pageAccessToken: string,
): Promise<InstagramContainerStatus> {
  const url = graphUrl(containerId, { fields: "status_code,status" });
  const res = await fetch(
    `${url}&access_token=${encodeURIComponent(pageAccessToken)}`,
  );
  const json = await res.json().catch(() => ({})) as {
    status_code?: string;
    status?: string;
    error?: { message?: string };
  };

  if (!res.ok) {
    throw new Error(
      `meta_reels_container_status HTTP ${res.status}: ${json.error?.message ?? "unknown"}`,
    );
  }

  return {
    statusCode: String(json.status_code ?? "").trim().toUpperCase(),
    status: json.status?.trim() ? String(json.status).trim() : null,
  };
}

/**
 * Poll IG media container until FINISHED (required before media_publish).
 * Throws media_not_ready on timeout; meta_reels_container_error/expired on fatal status.
 */
export async function waitForInstagramReelsContainerReady(
  containerId: string,
  pageAccessToken: string,
  options?: { maxWaitMs?: number; intervalMs?: number; onTick?: () => Promise<void> | void },
): Promise<InstagramContainerStatus> {
  const maxWaitMs = options?.maxWaitMs ?? DEFAULT_CONTAINER_MAX_WAIT_MS;
  const intervalMs = options?.intervalMs ?? DEFAULT_CONTAINER_POLL_MS;
  const deadline = Date.now() + maxWaitMs;
  let last: InstagramContainerStatus = { statusCode: "", status: null };

  while (Date.now() <= deadline) {
    if (options?.onTick) await options.onTick();
    last = await fetchInstagramContainerStatus(containerId, pageAccessToken);
    if (last.statusCode === IG_CONTAINER_READY) return last;
    if (IG_CONTAINER_FATAL.has(last.statusCode)) {
      const detail = last.status ? ` — ${last.status}` : "";
      throw new Error(
        `meta_reels_container_${last.statusCode.toLowerCase()}${detail}`,
      );
    }
    await sleepMs(intervalMs);
  }

  throw new Error(
    `media_not_ready: Instagram container status=${last.statusCode || "unknown"} after ${maxWaitMs}ms`,
  );
}

export async function publishInstagramReelsContainer(
  igBusinessAccountId: string,
  pageAccessToken: string,
  containerId: string,
): Promise<{ mediaId: string }> {
  const url = graphUrl(`${igBusinessAccountId}/media_publish`);
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      access_token: pageAccessToken,
      creation_id: containerId,
    }),
  });

  const json = await res.json().catch(() => ({})) as {
    id?: string;
    error?: { message?: string };
  };

  if (!res.ok || !json.id) {
    const msg = json.error?.message ?? "unknown";
    const lower = msg.toLowerCase();
    // Publish-before-ready / still processing — surface as transient media_not_ready.
    if (
      lower.includes("media id is not available") ||
      lower.includes("media is not ready") ||
      lower.includes("not ready for publishing")
    ) {
      throw new Error(`media_not_ready: ${msg}`);
    }
    throw new Error(`meta_reels_publish HTTP ${res.status}: ${msg}`);
  }

  return { mediaId: String(json.id) };
}

export async function fetchInstagramMediaPermalink(
  mediaId: string,
  pageAccessToken: string,
): Promise<string | null> {
  const url = graphUrl(mediaId, { fields: "permalink" });
  const res = await fetch(`${url}&access_token=${encodeURIComponent(pageAccessToken)}`);
  const json = await res.json().catch(() => ({})) as { permalink?: string };
  return json.permalink?.trim() ?? null;
}

export function buildInstagramReelsFallbackUrl(mediaId: string): string {
