async function executeFacebookCarouselScheduledPost(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
  plan: PlanRow,
): Promise<{ published_url: string; external_post_id: string | null }> {
  const storagePaths = assertCarouselPublishPaths(
    await loadCarouselStoragePaths(admin, plan.id),
  );
  const imageCount = storagePaths.length;
  if (!isPlanEligibleForFacebookAutoSchedule({
    ...planEligibilityInput(plan),
    carousel_image_count: imageCount,
  })) {
    throw new Error("plan_not_eligible");
  }
  if (schedule.media_url_snapshot !== carouselMediaSnapshot(storagePaths)) {
    throw new Error("carousel_images_changed");
  }

  const cfg = schedule.provider_config as FacebookProviderConfig;
  const pageId = String(cfg.facebook_page_id ?? "").trim();
  if (!pageId) throw new Error("missing_facebook_page_id");

  const account = await resolveMetaContentAccount(
    admin,
    schedule.organization_id,
    "facebook",
    pageId,
  );
  if (!account?.pageAccessToken) throw new Error("facebook_page_not_found");
  if (!facebookPublishScopesOk(account.grantedScopes)) {
    throw new Error("publish_scopes_not_granted");
  }

  let providerConfig = { ...(schedule.provider_config as Record<string, unknown>) };
  const caption = schedule.caption?.trim() || schedule.title?.trim() || "";
  const accountLabel = String(cfg.account_label ?? account.accountLabel ?? "Facebook");
  const heartbeat = () => touchPublishingHeartbeat(admin, [schedule.id]);

  const finalize = async (postId: string) => {
    const permalink = await fetchFacebookPostPermalink(postId, account.pageAccessToken);
    const publishedUrl = permalink ?? buildFacebookPhotoPostUrl(postId);
    await upsertFacebookLink(admin, plan, {
      url: publishedUrl,
      accountId: pageId,
      accountLabel,
      externalPostId: postId,
      employeeId: cfg.employee_id,
    });
    return { published_url: publishedUrl, external_post_id: postId };
  };

  let photoIds = storedFacebookPhotoIds(providerConfig);
  let postId = String(providerConfig.fb_carousel_post_id ?? "").trim();
  if (postId) {
    console.info(
      `facebook_publish_path=carousel scheduleId=${schedule.id} resume=1 images=${imageCount}`,
    );
    return finalize(postId);
  }
  if (photoIds.length > imageCount) throw new Error("carousel_images_changed");

  const imageUrls = facebookCarouselImageUrls(storagePaths);
  while (photoIds.length < imageUrls.length) {
    const single = imageUrls.length === 1;
    const uploaded = await uploadFacebookPagePhoto(pageId, account.pageAccessToken, {
      imageUrl: imageUrls[photoIds.length],
      published: single,
      caption: single ? caption : undefined,
    });
    photoIds = [...photoIds, uploaded.photoId];
    postId = uploaded.postId ?? "";
    providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
      fb_photo_ids: photoIds,
      ...(postId ? { fb_carousel_post_id: postId } : {}),
      fb_upload_phase: postId ? "published" : "photos",
      publish_step: postId ? "processing" : "uploading",
    });
    await heartbeat();
    if (postId) {
      console.info(
        `facebook_publish_path=carousel scheduleId=${schedule.id} images=${imageCount}`,
      );
      return finalize(postId);
    }
  }

  const created = await publishFacebookMultiPhotoPost(pageId, account.pageAccessToken, {
    photoIds,
    message: caption,
  });
  providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
    fb_photo_ids: photoIds,
    fb_carousel_post_id: created.postId,
    fb_upload_phase: "published",
    publish_step: "processing",
  });
  console.info(
    `facebook_publish_path=carousel scheduleId=${schedule.id} images=${imageCount}`,
  );
  return finalize(created.postId);
}

export async function executeFacebookScheduledPost(
  admin: SupabaseClient,
  schedule: ScheduledPostRow,
  sharedCtx?: SharedPublishContext,
): Promise<{ published_url: string; external_post_id: string | null }> {
  const plan = await loadPlan(admin, schedule.social_media_plan_id);
  if (!plan) throw new Error("plan_not_found");
  if (isStoryContentType(plan.content_type?.name)) {
    return executeFacebookStoryScheduledPost(admin, schedule);
  }
  if (isCarouselContentType(plan.content_type?.name)) {
    return executeFacebookCarouselScheduledPost(admin, schedule, plan);
  }
  if (!isPlanEligibleForFacebookAutoSchedule(planEligibilityInput(plan))) {
    throw new Error("plan_not_eligible");
  }
  if (shouldCancelScheduleDueToDriveMismatch(schedule.media_url_snapshot, plan.google_drive_link)) {
    throw new Error("google_drive_link_changed");
  }

  const cfg = schedule.provider_config as FacebookProviderConfig;
  const pageId = String(cfg.facebook_page_id ?? "").trim();
  if (!pageId) throw new Error("missing_facebook_page_id");

  const account = await resolveMetaContentAccount(
    admin,
    schedule.organization_id,
    "facebook",
    pageId,
  );
  if (!account?.pageAccessToken) {
    throw new Error("facebook_page_not_found");
  }
  if (!facebookPublishScopesOk(account.grantedScopes)) {
    throw new Error("publish_scopes_not_granted");
  }

  let providerConfig = { ...(schedule.provider_config as Record<string, unknown>) };
  const caption = schedule.caption?.trim() || schedule.title?.trim() || "";
  const accountLabel = String(cfg.account_label ?? account.accountLabel ?? "Facebook");

  const finalize = async (finalVideoId: string, postId: string | null) => {
    const permalink = await fetchFacebookReelPermalink(finalVideoId, account.pageAccessToken);
    const publishedUrl = permalink ?? buildFacebookReelFallbackUrl(pageId, finalVideoId);
    const externalPostId = postId ?? finalVideoId;
    await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
      fb_upload_phase: "published",
      fb_published_video_id: finalVideoId,
      publish_step: "processing",
    });
    await upsertFacebookLink(admin, plan, {
      url: publishedUrl,
      accountId: pageId,
      accountLabel,
      externalPostId,
      employeeId: cfg.employee_id,
    });
    return { published_url: publishedUrl, external_post_id: externalPostId };
  };

  let videoId = String(cfg.fb_video_id ?? "").trim();
  let uploadUrl = String(cfg.fb_upload_url ?? "").trim();
  let sessionCreatedNow = false;
  let progress: FacebookReelProgress = String(cfg.fb_upload_phase ?? "").trim() === "uploaded"
    ? "upload_complete"
    : "upload_needed";

  if (videoId) {
    try {
      const remote = await fetchFacebookReelStatus(videoId, account.pageAccessToken);
      progress = classifyFacebookReelStatus(remote);
      console.info(
        `facebook_status scheduleId=${schedule.id} videoId=${videoId} uploading=${remote.uploading} processing=${remote.processing} publishing=${remote.publishing} progress=${progress}`,
      );
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.warn(
        `facebook_status_unavailable scheduleId=${schedule.id} reason=${message.slice(0, 180)}`,
      );
    }
  }

  if (videoId && progress === "published") {
    return finalize(videoId, null);
  }

  if (progress === "error" || !videoId || (progress === "upload_needed" && !uploadUrl)) {
    const session = await startFacebookReelsUploadSession(pageId, account.pageAccessToken);
    videoId = session.videoId;
    uploadUrl = session.uploadUrl;
    progress = "upload_needed";
    sessionCreatedNow = true;
    providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
      fb_video_id: videoId,
      fb_upload_url: uploadUrl,
      fb_upload_phase: "started",
      publish_step: "uploading",
    });
  }

  if (progress === "upload_needed") {
    const driveUrl = plan.google_drive_link?.trim() || schedule.media_url_snapshot || "";
    const publicUrl = resolveGoogleDrivePublicVideoUrl(driveUrl);
    const heartbeat = () => touchPublishingHeartbeat(admin, [schedule.id]);

    if (publicUrl) {
      // A session left on "started" already has a binary upload attached. file_url needs a clean session.
      if (!sessionCreatedNow) {
        const session = await startFacebookReelsUploadSession(pageId, account.pageAccessToken);
        videoId = session.videoId;
        uploadUrl = session.uploadUrl;
        providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
          fb_video_id: videoId,
          fb_upload_url: uploadUrl,
          fb_upload_phase: "started",
          publish_step: "uploading",
        });
      }
      try {
        await uploadFacebookReelsFromUrl(uploadUrl, account.pageAccessToken, publicUrl);
        providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
          fb_upload_phase: "transfer",
          publish_step: "processing",
        });
        const waited = await waitForFacebookReelUpload(videoId, account.pageAccessToken, {
          onTick: heartbeat,
        });
        if (waited === "error") throw new Error("fb_file_url_processing_error");
        if (waited === "published") return finalize(videoId, null);
        progress = "upload_complete";
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        console.warn(
          `facebook_file_url_fallback scheduleId=${schedule.id} reason=${message.slice(0, 180)}`,
        );
        const session = await startFacebookReelsUploadSession(pageId, account.pageAccessToken);
        videoId = session.videoId;
        uploadUrl = session.uploadUrl;
        providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
          fb_video_id: videoId,
          fb_upload_url: uploadUrl,
          fb_upload_phase: "started",
          publish_step: "uploading",
        });
        const { bytes: videoBytes } = await resolveVideoBytesForUpload(driveUrl, sharedCtx);
        await uploadFacebookReelsVideo(uploadUrl, account.pageAccessToken, videoBytes);
        progress = "upload_complete";
      }
    } else {
      providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
        publish_step: "uploading",
      });
      const { bytes: videoBytes } = await resolveVideoBytesForUpload(driveUrl, sharedCtx);
      await uploadFacebookReelsVideo(uploadUrl, account.pageAccessToken, videoBytes);
      progress = "upload_complete";
    }

    providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
      fb_upload_phase: "uploaded",
      publish_step: "processing",
    });
  }

  providerConfig = await persistFacebookProviderConfig(admin, schedule.id, providerConfig, {
    publish_step: "processing",
  });
  const finished = await finishFacebookReelsPublish(pageId, account.pageAccessToken, {
    videoId,
    description: caption,
  });
  return finalize(finished.videoId, finished.postId);
}

import { graphUrl } from "../metaContentAuth.ts";
import {
  isFetchAbortError,
  PLATFORM_BYTE_UPLOAD_TIMEOUT_MS,
} from "../scheduledPosts/fetchTimeout.ts";

export type FacebookReelsStartResult = {
  videoId: string;
  uploadUrl: string;
};

export type FacebookReelsFinishResult = {
  videoId: string;
  postId: string | null;
};

function parseGraphError(json: unknown, fallback: string): string {
  const err = (json as { error?: { message?: string } })?.error?.message;
  return err?.trim() || fallback;
}

export async function startFacebookReelsUploadSession(
  pageId: string,
  pageAccessToken: string,
): Promise<FacebookReelsStartResult> {
  const url = graphUrl(`${pageId}/video_reels`);
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      access_token: pageAccessToken,
      upload_phase: "start",
    }),
  });

  const json = await res.json().catch(() => ({})) as {
    video_id?: string;
    upload_url?: string;
    error?: { message?: string };
  };

  if (!res.ok || !json.video_id) {
    throw new Error(
      `meta_fb_reels_start HTTP ${res.status}: ${parseGraphError(json, "unknown")}`,
    );
  }

  const uploadUrl = String(json.upload_url ?? "").trim();
  if (!uploadUrl) throw new Error("meta_fb_reels_missing_upload_url");

  return { videoId: String(json.video_id), uploadUrl };
}

const FACEBOOK_FILE_URL_TIMEOUT_MS = 45_000;
const FACEBOOK_TRANSFER_POLL_MS = 5_000;
const FACEBOOK_TRANSFER_MAX_WAIT_MS = 180_000;

/**
 * Ask Facebook to fetch a public video URL. The request itself is small;
 * Facebook downloads the file, then we poll status before finish.
 */
export async function uploadFacebookReelsFromUrl(
  uploadUrl: string,
  pageAccessToken: string,
  fileUrl: string,
): Promise<void> {
  const started = Date.now();
  let res: Response;
  try {
    res = await fetch(uploadUrl, {
      method: "POST",
      headers: {
        Authorization: `OAuth ${pageAccessToken}`,
        file_url: fileUrl,
      },
      signal: AbortSignal.timeout(FACEBOOK_FILE_URL_TIMEOUT_MS),
    });
  } catch (err) {
    if (isFetchAbortError(err)) {
      throw new Error(
        `fb_file_url_timeout: Facebook did not accept the video URL in ${FACEBOOK_FILE_URL_TIMEOUT_MS}ms`,
      );
    }
    throw err;
  }

  const text = await res.text().catch(() => "");
  if (!res.ok) {
    throw new Error(`meta_fb_reels_file_url HTTP ${res.status}: ${text.slice(0, 300)}`);
  }
  try {
    const json = JSON.parse(text) as { success?: boolean };
    if (json.success === false) {
      throw new Error(`meta_fb_reels_file_url rejected: ${text.slice(0, 300)}`);
    }
  } catch (err) {
    if (err instanceof Error && err.message.startsWith("meta_fb_reels_file_url")) throw err;
  }
  console.info(`facebook_file_url_ok ms=${Date.now() - started}`);
}

export async function waitForFacebookReelUpload(
  videoId: string,
  pageAccessToken: string,
  options?: { onTick?: () => Promise<void>; maxWaitMs?: number },
): Promise<FacebookReelProgress> {
  const deadline = Date.now() + (options?.maxWaitMs ?? FACEBOOK_TRANSFER_MAX_WAIT_MS);
  let last = "upload_needed";
  while (Date.now() <= deadline) {
    if (options?.onTick) await options.onTick();
    const snap = await fetchFacebookReelStatus(videoId, pageAccessToken);
    const progress = classifyFacebookReelStatus(snap);
    last = `${snap.uploading}/${snap.processing}/${snap.publishing}/${progress}`;
    console.info(`facebook_transfer_status videoId=${videoId} ${last}`);
    if (progress !== "upload_needed") return progress;
    const remaining = deadline - Date.now();
    if (remaining <= 0) break;
    await new Promise((resolve) => setTimeout(resolve, Math.min(FACEBOOK_TRANSFER_POLL_MS, remaining)));
  }
  throw new Error(`fb_file_url_timeout: Facebook did not finish fetching the video (${last})`);
}

export async function uploadFacebookReelsVideo(
  uploadUrl: string,
  pageAccessToken: string,
  videoBytes: Uint8Array,
): Promise<void> {
  const started = Date.now();
  let res: Response;
  try {
    res = await fetch(uploadUrl, {
      method: "POST",
      headers: {
        Authorization: `OAuth ${pageAccessToken}`,
        "Content-Type": "application/octet-stream",
        offset: "0",
        file_size: String(videoBytes.byteLength),
      },
      body: videoBytes,
      signal: AbortSignal.timeout(PLATFORM_BYTE_UPLOAD_TIMEOUT_MS),
    });
  } catch (err) {
    if (isFetchAbortError(err)) {
      throw new Error(
        `fb_upload_timeout: Facebook upload did not finish in ${PLATFORM_BYTE_UPLOAD_TIMEOUT_MS}ms`,
      );
    }
    throw err;
  }

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`meta_fb_reels_upload HTTP ${res.status}: ${text.slice(0, 300)}`);
  }
  console.info(
    `facebook_upload_ok bytes=${videoBytes.byteLength} ms=${Date.now() - started}`,
  );
}

export type FacebookReelStatusSnapshot = {
  videoStatus: string;
  uploading: string;
  processing: string;
  publishing: string;
};

export type FacebookReelProgress =
  | "published"
  | "upload_complete"
  | "processing"
  | "upload_needed"
  | "error";

/** Map Graph video status into the next local action. Missing upload means bytes still have to be sent. */
export function classifyFacebookReelStatus(
  snapshot: FacebookReelStatusSnapshot,
): FacebookReelProgress {
  const publishing = snapshot.publishing.trim().toLowerCase();
  const uploading = snapshot.uploading.trim().toLowerCase();
  const processing = snapshot.processing.trim().toLowerCase();
  const video = snapshot.videoStatus.trim().toLowerCase();

  if (publishing === "complete" || video === "ready") return "published";
  if (uploading === "error" || processing === "error" || publishing === "error" || video === "error") {
    return "error";
  }
  if (uploading === "complete" || uploading === "completed") {
    return processing === "in_progress" ? "processing" : "upload_complete";
  }
  return "upload_needed";
}

export async function fetchFacebookReelStatus(
  videoId: string,
  pageAccessToken: string,
): Promise<FacebookReelStatusSnapshot> {
  const url = graphUrl(videoId, { fields: "status" });
  const res = await fetch(`${url}&access_token=${encodeURIComponent(pageAccessToken)}`);
  const json = await res.json().catch(() => ({})) as {
    status?: {
      video_status?: string;
      uploading_phase?: { status?: string };
      processing_phase?: { status?: string };
      publishing_phase?: { status?: string };
    };
    error?: { message?: string };
  };
  if (!res.ok) {
    throw new Error(
      `meta_fb_reels_status HTTP ${res.status}: ${json.error?.message ?? "unknown"}`,
    );
  }
  const status = json.status ?? {};
  return {
    videoStatus: String(status.video_status ?? ""),
    uploading: String(status.uploading_phase?.status ?? ""),
    processing: String(status.processing_phase?.status ?? ""),
    publishing: String(status.publishing_phase?.status ?? ""),
  };
}

export async function finishFacebookReelsPublish(
  pageId: string,
  pageAccessToken: string,
  args: { videoId: string; description: string },
): Promise<FacebookReelsFinishResult> {
  const url = graphUrl(`${pageId}/video_reels`);
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      access_token: pageAccessToken,
      upload_phase: "finish",
      video_id: args.videoId,
      video_state: "PUBLISHED",
      description: args.description.slice(0, 2200),
    }),
  });

  const json = await res.json().catch(() => ({})) as {
    video_id?: string;
    post_id?: string;
    success?: boolean;
    error?: { message?: string; code?: number };
  };

  if (!res.ok || json.success === false) {
    const msg = parseGraphError(json, "unknown");
    if (msg.toLowerCase().includes("limit") || json.error?.code === 368) {
      throw new Error(`meta_fb_reels_rate_limit: ${msg}`);
    }
    throw new Error(`meta_fb_reels_finish HTTP ${res.status}: ${msg}`);
  }

  return {
    videoId: String(json.video_id ?? args.videoId),
    postId: json.post_id ? String(json.post_id) : null,
  };
}

export async function fetchFacebookReelPermalink(
  videoId: string,
  pageAccessToken: string,
): Promise<string | null> {
  const url = graphUrl(videoId, { fields: "permalink_url,permalink" });
  const res = await fetch(`${url}&access_token=${encodeURIComponent(pageAccessToken)}`);
  const json = await res.json().catch(() => ({})) as {
    permalink_url?: string;
    permalink?: string;
  };
  return json.permalink_url?.trim() || json.permalink?.trim() || null;
}

export function buildFacebookReelFallbackUrl(pageId: string, videoId: string): string {
  return `https://www.facebook.com/${encodeURIComponent(pageId)}/videos/${encodeURIComponent(videoId)}/`;
}

/** Reel permalinks carry the video id, the only delete target that survives resume cleanup. */
export function extractFacebookVideoIdFromUrl(url: string | null | undefined): string | null {
  const raw = String(url ?? "").trim();
  if (!raw) return null;
  const patterns = [
    /\/videos\/(?:[^/?#]+\/)?(\d{5,})/,
    /\/reels?\/(\d{5,})/,
    /[?&]v=(\d{5,})/,
  ];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) return match[1];
  }
  return null;
}

type GraphDeleteAttempt = {
  ok: boolean;
  missingObject: boolean;
  error?: string;
};

async function graphDeleteObject(
  objectId: string,
  pageAccessToken: string,
): Promise<GraphDeleteAttempt> {
  const url = graphUrl(encodeURIComponent(objectId));
  const res = await fetch(`${url}?access_token=${encodeURIComponent(pageAccessToken)}`, {
    method: "DELETE",
  });
  const json = await res.json().catch(() => ({})) as {
    success?: boolean;
    error?: { message?: string; code?: number };
  };

  if (res.ok && json.success !== false) {
    return { ok: true, missingObject: false };
  }

  const code = json.error?.code;
  const message = json.error?.message ?? `http_${res.status}`;
  const lower = message.toLowerCase();
  const missingObject = code === 100 && lower.includes("does not exist");

  return { ok: false, missingObject, error: message };
}

export type FacebookDeleteContentResult = {
  ok: boolean;
  alreadyDeleted: boolean;
  deletedTarget?: string;
  error?: string;
};

/**
 * Graph rejects a bare Page post id with error #12 (singular statuses API deprecated),
 * so try every known id shape (video node, `{page}_{post}`, raw id) before failing.
 */
export async function deleteFacebookPublishedContent(
  candidateIds: readonly string[],
  pageAccessToken: string,
): Promise<FacebookDeleteContentResult> {
  const attempted = new Set<string>();
  const failures: string[] = [];
  let missingObject = false;

  for (const candidate of candidateIds) {
    const target = candidate.trim();
    if (!target || attempted.has(target)) continue;
    attempted.add(target);

    const attempt = await graphDeleteObject(target, pageAccessToken);
    if (attempt.ok) {
      return { ok: true, alreadyDeleted: false, deletedTarget: target };
    }
    if (attempt.missingObject) missingObject = true;
    failures.push(`${target}: ${attempt.error ?? "unknown"}`);
  }

  if (attempted.size === 0 || missingObject) {
    return { ok: true, alreadyDeleted: true };
  }

  return { ok: false, alreadyDeleted: false, error: failures.join(" | ") };
}

export async function deleteInstagramMedia(
  mediaId: string,
  pageAccessToken: string,
): Promise<{ ok: boolean; alreadyDeleted: boolean; error?: string }> {
  const url = graphUrl(mediaId);
  const res = await fetch(`${url}?access_token=${encodeURIComponent(pageAccessToken)}`, {
    method: "DELETE",
  });
  const json = await res.json().catch(() => ({})) as {
    success?: boolean;
    error?: { message?: string; code?: number };
  };

  if (res.ok && json.success !== false) {
    return { ok: true, alreadyDeleted: false };
  }

  const code = json.error?.code;
  const msg = json.error?.message ?? "";
  if (code === 100 || msg.toLowerCase().includes("not exist")) {
    return { ok: true, alreadyDeleted: true };
  }

  return { ok: false, alreadyDeleted: false, error: msg || `http_${res.status}` };
}

import { graphUrl } from "../metaContentAuth.ts";
import { publicCarouselImageUrl } from "./instagramCarouselPublishApi.ts";

const FB_MESSAGE_LIMIT = 5000;

export type FacebookPagePhotoResult = {
  photoId: string;
  postId: string | null;
};

export function facebookCarouselImageUrls(storagePaths: string[]): string[] {
  const supabaseUrl = Deno.env.get("SUPABASE_URL")?.trim() ?? "";
  if (!supabaseUrl) throw new Error("supabase_url_missing");
  return storagePaths.map((storagePath) => publicCarouselImageUrl(supabaseUrl, storagePath));
}

/** Form fields for a Page feed post that attaches already uploaded photos. */
export function facebookAttachedMediaFields(photoIds: string[]): Record<string, string> {
  const fields: Record<string, string> = {};
  photoIds.forEach((photoId, index) => {
    const id = photoId.trim();
    if (!id) throw new Error("facebook_photo_id_missing");
    fields[`attached_media[${index}]`] = JSON.stringify({ media_fbid: id });
  });
  return fields;
}

export function buildFacebookPhotoPostUrl(postId: string): string {
  return `https://www.facebook.com/${postId}`;
}

async function readGraphId(res: Response, label: string): Promise<{ id: string; postId: string | null }> {
  const json = await res.json().catch(() => ({})) as {
    id?: string;
    post_id?: string;
    error?: { message?: string };
  };
  if (!res.ok || !json.id) {
    throw new Error(
      `${label} HTTP ${res.status}: ${json.error?.message ?? "unknown"}`,
    );
  }
  const postId = String(json.post_id ?? "").trim();
  return { id: String(json.id), postId: postId || null };
}

export async function uploadFacebookPagePhoto(
  pageId: string,
  pageAccessToken: string,
  args: { imageUrl: string; published: boolean; caption?: string },
): Promise<FacebookPagePhotoResult> {
  const params: Record<string, string> = {
    access_token: pageAccessToken,
    url: args.imageUrl,
    published: args.published ? "true" : "false",
  };
  if (args.published && args.caption?.trim()) {
    params.caption = args.caption.trim().slice(0, FB_MESSAGE_LIMIT);
  }

  const res = await fetch(graphUrl(`${pageId}/photos`), {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(params),
    signal: AbortSignal.timeout(45_000),
  });
  const created = await readGraphId(res, "meta_fb_photo");
  return { photoId: created.id, postId: created.postId };
}

export async function publishFacebookMultiPhotoPost(
  pageId: string,
  pageAccessToken: string,
  args: { photoIds: string[]; message: string },
): Promise<{ postId: string }> {
  if (args.photoIds.length < 1 || args.photoIds.length > 10) {
    throw new Error("facebook_carousel_count");
  }
  const res = await fetch(graphUrl(`${pageId}/feed`), {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      access_token: pageAccessToken,
      message: args.message.trim().slice(0, FB_MESSAGE_LIMIT),
      ...facebookAttachedMediaFields(args.photoIds),
    }),
    signal: AbortSignal.timeout(45_000),
  });
  const created = await readGraphId(res, "meta_fb_feed");
  return { postId: created.postId ?? created.id };
}

export async function fetchFacebookPostPermalink(
  postId: string,
  pageAccessToken: string,
): Promise<string | null> {
  const url = graphUrl(postId, { fields: "permalink_url" });
  const res = await fetch(`${url}&access_token=${encodeURIComponent(pageAccessToken)}`);
  const json = await res.json().catch(() => ({})) as { permalink_url?: string };
  const permalink = json.permalink_url?.trim() ?? "";
  if (!permalink) return null;
  if (permalink.startsWith("http://") || permalink.startsWith("https://")) return permalink;
  return `https://www.facebook.com${permalink.startsWith("/") ? "" : "/"}${permalink}`;
}

